def p_complete(n, a=0.04, b=0.20):
    return b / (a + b) * (1 - a) ** (n - 1)

print(round(p_complete(3), 3), round(p_complete(1), 3))

prio = {"A": 5, "B": 3, "C": 4}
length = {"A": 3, "B": 1, "C": 2}
window = {"A": range(2, 6), "B": range(0, 2), "C": range(0, 3)}
k, done, plan = 0, set(), []
while k < 6:
    ready = [t for t in prio if t not in done and k in window[t]]
    if not ready:
        k += 1
        continue
    t = max(ready, key=lambda x: prio[x])
    plan.append((t, k)); done.add(t); k += length[t]
print(plan)
